mapper.select:
select coalesce(max(result), 0)
from play_attempt_log
where member_id = #{memberId}
  and topic_id = #{topicId}
  and node_id = #{nodeId}
  and activity_id = #{activityId}
  and attempt_type = 5

select node_id as nodeId, max(result) as hintLevel
from play_attempt_log
where member_id = #{memberId}
  and topic_id = #{topicId}
  and activity_id = #{activityId}
  and attempt_type = 5
group by node_id
